public class Main {
    public static void main(String[] args) {
        Diskon d = new DiskonMember();
        System.out.println(d.potong(50000));
    }
}

interface Diskon {
    int potong(int harga);
}

class DiskonMember implements Diskon {
    public int potong(int harga) {
        return harga - 5000;
    }
}

public class Main {
    public static void main(String[] args) {
        Diskon d = new DiskonMember();
        System.out.println(d.potong(50000));
        Diskon d2 = new DiskonPersen(20);
        System.out.println(d2.potong(50000));
    }
}

interface Diskon {
    int potong(int harga);
}

class DiskonMember implements Diskon {
    public int potong(int harga) {
        return harga - 5000;
    }
}

class DiskonPersen implements Diskon {
    int persen;

    DiskonPersen(int persen) {
        this.persen = persen;
    }

    public int potong(int harga) {
        return harga - harga * persen / 100;
    }
}

public class Main {
    public static void main(String[] args) {
        Diskon d = new DiskonMember();
        System.out.println(d.potong(50000));
        Diskon d2 = new DiskonPersen(20);
        System.out.println(d2.potong(50000));
        Diskon[] semua = {d, d2};
        for (Diskon x : semua) {
            System.out.println(x.potong(100000));
        }
    }
}

interface Diskon {
    int potong(int harga);
}

class DiskonMember implements Diskon {
    public int potong(int harga) {
        return harga - 5000;
    }
}

class DiskonPersen implements Diskon {
    int persen;

    DiskonPersen(int persen) {
        this.persen = persen;
    }

    public int potong(int harga) {
        return harga - harga * persen / 100;
    }
}

